INSERT OR REPLACE INTO ec_case_studies ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "client", "sector", "role", "summary", "cover", "year", "featured", "published", "live_url", "outcome", "designer_note", "body", "showcase_desktop", "showcase_mobile", "showcase_alt", "showcase_href", "showcase_label", "showcase_variant", "highlights", "results") VALUES ('01M3ZCX9P93QJ1AMS8HMHVJRSB', 'presbyterian-academy', 'published', '2026-10-02T22:49:11.113Z', '2026-10-02T23:19:28.024Z', '2026-10-02T22:49:12.607Z', 8, 'en', '01M3ZCX9P93QJ1AMS8HMHVJRSB', 'The Presbyterian Academy', 'The Presbyterian Academy', 'school', 'Designer, Developer', 'A launch site for a brand-new Reformed lay formation school that needed to explain what it is, who it''s for, and how to enroll, all before the first cohort began.', '{"id":"01M3ZCX2FXJ1J7KBZ45364JT0M","provider":"local","filename":"presbyterian-academy.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LcOzJO~qs:D%RjR*ayxaW=MxWBxu","dominantColor":"rgb(204,201,193)","alt":"The The Presbyterian Academy homepage","meta":{"storageKey":"5P1BMZTRQV4SA72BZHBZ1XHMD9.png","caption":null,"blurhash":"LcOzJO~qs:D%RjR*ayxaW=MxWBxu","dominantColor":"rgb(204,201,193)"}}', 2026, 1, '2026-06-15T00:00:00.000Z', 'https://www.presbyterianacademy.org', 'A credible front door for a brand-new school: clear catalog, real faculty, honest pricing.', 'The hardest call on this one was pricing. Everybody told me to bury the numbers and make people call, but this audience is weighing a semester-long commitment, and they respect being given straight answers. Putting the tiers and the scholarship process out in the open drew the people who were actually ready to think about enrolling, which is worth far more than the leads you lose by showing the numbers early.', '[{"_key":"k41","_type":"block","children":[{"_key":"k40","_type":"span","marks":[],"text":"The brief"}],"markDefs":[],"style":"h2"},{"_key":"k43","_type":"block","children":[{"_key":"k42","_type":"span","marks":[],"text":"The Presbyterian Academy is a Reformed lay formation school launched in 2026 by the Presbytery of Cincinnati. The mission is adult theological education in cohort form: semester-length in-person courses for people who want to study Reformed theology seriously but are not pursuing ordination. There is nothing quite like it in the region."}],"markDefs":[],"style":"normal"},{"_key":"k45","_type":"block","children":[{"_key":"k44","_type":"span","marks":[],"text":"They came to us with the name, the faculty, and a start date. The site needed to do three things before the first enrollment cycle closed: explain what the Academy is, establish that it is serious, and convert interested visitors into enrolled students or at minimum a scheduled intro call."}],"markDefs":[],"style":"normal"},{"_key":"k47","_type":"block","children":[{"_key":"k46","_type":"span","marks":[],"text":"The approach"}],"markDefs":[],"style":"h2"},{"_key":"k49","_type":"block","children":[{"_key":"k48","_type":"span","marks":[],"text":"Brand-new organizations have a trust problem that established ones do not. There is no press coverage to cite, no multi-year alumni network to quote, and no decades of institutional history to point to. The site had to build credibility from what actually existed: a compelling faculty roster, specific course descriptions, and pricing that did not hedge."}],"markDefs":[],"style":"normal"},{"_key":"k4b","_type":"block","children":[{"_key":"k4a","_type":"span","marks":[],"text":"We organized the architecture around three conversion questions in sequence. What is this? Is it for me? How do I start? Every page answers at least one of those. The homepage handles the first. The course catalog and faculty directory handle the second. The enrollment and contact pages handle the third."}],"markDefs":[],"style":"normal"},{"_key":"k4d","_type":"block","children":[{"_key":"k4c","_type":"span","marks":[],"text":"For the visual language, we landed on what we called bookish minimalism: warm near-white paper tones, near-black ink, deep forest green anchoring the palette, and brass hairlines as structural dividers. Display type in Fraunces paired with Source Sans 3 for body. No hero photography of empty lecture halls; the design is text-forward because the product is text-forward."}],"markDefs":[],"style":"normal"},{"_key":"k4f","_type":"block","children":[{"_key":"k4e","_type":"span","marks":[],"text":"The CMS runs on Sanity so the Academy team can update courses, faculty, terms, and enrollment status from a dashboard without involving a developer."}],"markDefs":[],"style":"normal"},{"_key":"k4h","_type":"block","children":[{"_key":"k4g","_type":"span","marks":[],"text":"What we built"}],"markDefs":[],"style":"h2"},{"_key":"k4j","_type":"block","children":[{"_key":"k4i","_type":"span","marks":[],"text":"The full build, including the pieces above:"}],"markDefs":[],"style":"normal"},{"_key":"k4l","_type":"block","children":[{"_key":"k4k","_type":"span","marks":[],"text":"Course catalog with individual course pages, including a sticky enrollment-action aside on desktop so the sign-up path stays visible while visitors read the course description"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4n","_type":"block","children":[{"_key":"k4m","_type":"span","marks":[],"text":"Faculty directory with full biographical profiles, written to establish the weight of the teaching roster"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4p","_type":"block","children":[{"_key":"k4o","_type":"span","marks":[],"text":"Term listings showing enrollment periods with open/closed status and upcoming dates"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4r","_type":"block","children":[{"_key":"k4q","_type":"span","marks":[],"text":"Pricing tiers and need-based scholarship information, presented without \"contact us for pricing\" hedging, because the audience making a semester-long commitment deserves straight numbers"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4t","_type":"block","children":[{"_key":"k4s","_type":"span","marks":[],"text":"Testimonials section seeded from early cohort participants"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4v","_type":"block","children":[{"_key":"k4u","_type":"span","marks":[],"text":"Express interest form connected to Web3Forms for visitors who are ready to raise their hand"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4x","_type":"block","children":[{"_key":"k4w","_type":"span","marks":[],"text":"Calendly integration for intro call scheduling alongside the form"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4z","_type":"block","children":[{"_key":"k4y","_type":"span","marks":[],"text":"Homepage with a six-image Ken Burns slideshow hero that sets an academic, bookish tone without requiring event photography"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k51","_type":"block","children":[{"_key":"k50","_type":"span","marks":[],"text":"Enrollment status live in the site header so every page shows whether the current term is open or closed"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k53","_type":"block","children":[{"_key":"k52","_type":"span","marks":[],"text":"Full Sanity CMS for courses, faculty, terms, testimonials, and configuration"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}]', '{"id":"01M3ZCX3SY8MT9DHJJB1HDK899","provider":"local","filename":"presbyterian-academy-home.png","mimeType":"image/png","width":1425,"height":5690,"blurhash":"LkNKCm%Mofof~qxuoeWB00t7afRj","dominantColor":"rgb(173,176,169)","alt":"The Presbyterian Academy homepage, scrolling top to bottom","meta":{"storageKey":"6VJW1CPXN36GRFKV8SSH7C7WDY.png","caption":null,"blurhash":"LkNKCm%Mofof~qxuoeWB00t7afRj","dominantColor":"rgb(173,176,169)"}}', '{"id":"01M3ZCX58Q6S7B9FMB6ZGE1T6Y","provider":"local","filename":"presbyterian-academy-mobile.png","mimeType":"image/png","width":545,"height":4000,"blurhash":"L6Qvq8IU9F~p00-:-:tR00og%Mof","dominantColor":"rgb(221,220,215)","alt":"","meta":{"storageKey":"5CVH2VBJNT0WVQBMY402YGYGMR.png","caption":null,"blurhash":"L6Qvq8IU9F~p00-:-:tR00og%Mof","dominantColor":"rgb(221,220,215)"}}', 'The Presbyterian Academy homepage, scrolling top to bottom', 'https://www.presbyterianacademy.org', 'presbyterianacademy.org', 'scroll', '[{"alt":"The Presbyterian Academy course catalog","caption":"Every course shows its topic, teacher, term, and price at a glance, with an open or waitlist status, so a visitor can size up the fit without emailing to ask.","image":{"alt":"The Presbyterian Academy course catalog","blurhash":"LPRMYrIU-;.8_2xuWBoe~q-;D%Rj","dominantColor":"rgb(231,230,228)","filename":"presbyterian-academy-feature-catalog.png","height":900,"id":"01M3ZCX6D07AJ9C5CCJFZDHM4F","meta":{"blurhash":"LPRMYrIU-;.8_2xuWBoe~q-;D%Rj","caption":null,"dominantColor":"rgb(231,230,228)","storageKey":"2YVF445SYZ39E88JGXV34J867A.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"left","title":"A catalog that answers ''is it for me?''"},{"alt":"The Presbyterian Academy faculty directory","caption":"A full profile for every teacher, each an ordained minister or credentialed scholar, does the trust-building a brand-new school cannot lean on history for.","image":{"alt":"The Presbyterian Academy faculty directory","blurhash":"LES6JRxuofxu~qt6t7xu-;t7Rj%M","dominantColor":"rgb(239,237,233)","filename":"presbyterian-academy-feature-faculty.png","height":900,"id":"01M3ZCX7F811AGFGG1M3NQSPWN","meta":{"blurhash":"LES6JRxuofxu~qt6t7xu-;t7Rj%M","caption":null,"dominantColor":"rgb(239,237,233)","storageKey":"14FXBA45R0VWHANQF41TWFYSBH.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"right","title":"Credibility from the people teaching"}]', '[{"text":"A brand-new school now has a credible front door, with a clear catalog, real faculty, and honest pricing, ready for its first enrollment cycle."},{"text":"An interested visitor can size up the fit, then take a clear next step through the express-interest form or an intro call."},{"text":"Full faculty profiles and a course catalog now do the credibility work a brand-new institution cannot lean on history for."},{"text":"The Academy team can update courses, faculty, terms, and enrollment status from a dashboard without involving a developer."},{"text":"Pricing tiers and the scholarship process are published up front, with no \"contact us for pricing\" hedging."}]');
INSERT OR REPLACE INTO ec_case_studies ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "client", "sector", "role", "summary", "cover", "year", "featured", "published", "live_url", "outcome", "designer_note", "body", "showcase_desktop", "showcase_mobile", "showcase_alt", "showcase_href", "showcase_label", "showcase_variant", "results") VALUES ('01M3ZCXHQNQCFMX8JK1J5W5851', 'reid-design', 'published', '2026-10-02T22:49:19.349Z', '2026-10-02T23:19:34.538Z', '2026-10-02T22:49:20.787Z', 8, 'en', '01M3ZCXHQNQCFMX8JK1J5W5851', 'Reid Design', 'Reid Design', 'small-business', 'Designer, Developer', 'A portfolio and booking site for an Indianapolis interior designer that turns browsers into qualified consultation requests before they ever pick up the phone.', '{"id":"01M3ZCXDCHRQT9FWS4F3Z8BHWG","provider":"local","filename":"reid-design.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LoFiDMt7fQj[~pj[ayj[?bofayj[","dominantColor":"rgb(113,110,106)","alt":"The Reid Design homepage","meta":{"storageKey":"1QBG5KEP3QXSGKBVNGDMJG791N.png","caption":null,"blurhash":"LoFiDMt7fQj[~pj[ayj[?bofayj[","dominantColor":"rgb(113,110,106)"}}', 2026, 1, '2026-05-15T00:00:00.000Z', 'https://www.reiddesignllc.com', 'Turns browsers into qualified consultation requests before they ever pick up the phone.', 'The detail I keep coming back to is the before/after slider. Finished rooms always photograph well, but until you can see the starting point, you cannot tell whether the change is something that could happen in your own house.', '[{"_key":"k55","_type":"block","children":[{"_key":"k54","_type":"span","marks":[],"text":"The brief"}],"markDefs":[],"style":"h2"},{"_key":"k57","_type":"block","children":[{"_key":"k56","_type":"span","marks":[],"text":"Staci Perkins runs Reid Design out of Plainfield, Indiana, serving homeowners across the Greater Indianapolis suburbs with everything from a single consultation hour to full-service room transformations. The work is genuinely strong. The existing digital presence was not."}],"markDefs":[],"style":"normal"},{"_key":"k59","_type":"block","children":[{"_key":"k58","_type":"span","marks":[],"text":"The brief had two parts. First, make the portfolio actually work as a sales tool, not just a gallery of nice rooms. Second, build something Staci can keep updated herself as new projects finish. Her ideal outcome was a site that does meaningful qualification work before a lead ever calls her."}],"markDefs":[],"style":"normal"},{"_key":"k5b","_type":"block","children":[{"_key":"k5a","_type":"span","marks":[],"text":"The approach"}],"markDefs":[],"style":"h2"},{"_key":"k5d","_type":"block","children":[{"_key":"k5c","_type":"span","marks":[],"text":"Interior design clients almost always have two blockers early in the process: they do not know what things cost, and they do not know whether their taste matches what the designer actually does. We built around both of those."}],"markDefs":[],"style":"normal"},{"_key":"k5f","_type":"block","children":[{"_key":"k5e","_type":"span","marks":[],"text":"The portfolio needed before/after pairs, not just finished rooms. Seeing the starting point is what makes the transformation land. The filter chips let visitors sort by room type and style so someone looking for a farmhouse kitchen can go straight to those projects instead of scrolling past twenty results that do not apply to them."}],"markDefs":[],"style":"normal"},{"_key":"k5h","_type":"block","children":[{"_key":"k5g","_type":"span","marks":[],"text":"For the pricing question, we built a Budget Calculator that lets visitors build their own scope estimate. It is not a quote; it is a self-qualification tool. Someone who walks through a full primary suite renovation and sees a range they can stomach is a much warmer lead than someone who calls cold with no idea what to expect. The Style Quiz serves a similar function on the creative side: it identifies a visitor''s design archetype and primes both the client and Staci for a more productive first call."}],"markDefs":[],"style":"normal"},{"_key":"k5j","_type":"block","children":[{"_key":"k5i","_type":"span","marks":[],"text":"We chose Astro and Sanity so Staci can add new projects, publish journal posts, and update press coverage without touching a line of code."}],"markDefs":[],"style":"normal"},{"_key":"k5l","_type":"block","children":[{"_key":"k5k","_type":"span","marks":[],"text":"What we built"}],"markDefs":[],"style":"h2"},{"_key":"k5n","_type":"block","children":[{"_key":"k5m","_type":"span","marks":[],"text":"Portfolio with before/after comparison sliders and Room x Style filter chips so visitors can find relevant work fast"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5p","_type":"block","children":[{"_key":"k5o","_type":"span","marks":[],"text":"Budget Calculator with room type, scope, and add-on selectors that outputs an estimated project range"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5r","_type":"block","children":[{"_key":"k5q","_type":"span","marks":[],"text":"Style Quiz that identifies a visitor''s design archetype and primes them for the consultation call"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5t","_type":"block","children":[{"_key":"k5s","_type":"span","marks":[],"text":"E-design service page for productized remote design, built with a toggleable coming-soon state while Staci prepares the offering"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5v","_type":"block","children":[{"_key":"k5u","_type":"span","marks":[],"text":"Lead magnet download hub with email capture for guides and planning resources"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5x","_type":"block","children":[{"_key":"k5w","_type":"span","marks":[],"text":"Affiliate shop (\"Shop My Favorites\") organized by room type with FTC disclosure built into the page design"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5z","_type":"block","children":[{"_key":"k5y","_type":"span","marks":[],"text":"Journal with seven custom content block types covering project walkthroughs, product roundups, and process breakdowns"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k61","_type":"block","children":[{"_key":"k60","_type":"span","marks":[],"text":"Press coverage strip for earned media and magazine features"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k63","_type":"block","children":[{"_key":"k62","_type":"span","marks":[],"text":"Resources hub that ties the quiz, calculator, and guides together in one place so visitors can self-serve before reaching out"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k65","_type":"block","children":[{"_key":"k64","_type":"span","marks":[],"text":"Full Sanity CMS for portfolio projects, journal posts, press entries, and site-wide configuration"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}]', '{"id":"01M3ZCXEMV6HM8J9G1T9G39T67","provider":"local","filename":"reid-design-home.png","mimeType":"image/png","width":1425,"height":8553,"alt":"The Reid Design homepage, scrolling top to bottom","meta":{"storageKey":"7XE0BA144DPJ0D26A7YJEGT3N3.png","caption":null,"blurhash":null,"dominantColor":null}}', '{"id":"01M3ZCXFRBMBAGRY0NYWDCHNX6","provider":"local","filename":"reid-design-mobile.png","mimeType":"image/png","width":545,"height":4000,"blurhash":"L9P6?W^Q%J~q00eAa^Rj00S~IqNG","dominantColor":"rgb(204,200,196)","alt":"","meta":{"storageKey":"1KE5KX7WTQCKFV5EJK42ZKEG95.png","caption":null,"blurhash":"L9P6?W^Q%J~q00eAa^Rj00S~IqNG","dominantColor":"rgb(204,200,196)"}}', 'The Reid Design homepage, scrolling top to bottom', 'https://www.reiddesignllc.com', 'reiddesignllc.com', 'scroll', '[{"text":"By the time someone books a consultation, the site has already walked them through scope and style, so the first call starts from shared understanding instead of square one."},{"text":"Before/after sliders turned the portfolio from an aspirational gallery into something persuasive, so visitors can see whether a transformation could happen in their own house."},{"text":"The Budget Calculator lets homeowners self-qualify on price by building their own scope estimate before they ever call."},{"text":"Staci can add new projects, publish journal posts, and update press coverage herself without touching a line of code."},{"text":"Filter chips let visitors sort by room type and style, so someone after a farmhouse kitchen goes straight to relevant work instead of scrolling past projects that do not apply."}]');
INSERT OR REPLACE INTO ec_case_studies ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "client", "sector", "role", "summary", "cover", "year", "featured", "published", "live_url", "outcome", "designer_note", "body", "showcase_desktop", "showcase_mobile", "showcase_alt", "showcase_href", "showcase_label", "showcase_variant", "highlights", "before_image", "before_alt", "before_label", "after_image", "after_alt", "after_label", "results") VALUES ('01M3ZCVAAJR0RXJ6TC4SYQF825', 'second-presbyterian-chicago', 'published', '2026-10-02T22:48:06.226Z', '2026-10-02T23:19:40.368Z', '2026-10-02T22:48:07.673Z', 10, 'en', '01M3ZCVAAJR0RXJ6TC4SYQF825', 'Second Presbyterian Church of Chicago', 'Second Presbyterian Church of Chicago', 'church', 'Designer, Developer', 'A full rebuild from Squarespace that organized a historic congregation''s deep programming behind a clear front door for first-time visitors.', '{"id":"01M3ZCPCKQKHGQKJW4XNYNKTB3","provider":"local","filename":"second-presbyterian-chicago.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)","alt":"The Second Presbyterian Church of Chicago homepage","meta":{"storageKey":"3YFB3122TA96GZZ57DZM67WXMZ.png","caption":null,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)"}}', 2026, 1, '2026-05-01T00:00:00.000Z', 'https://www.secondpreschicago.org', 'A historic congregation''s deep programming, finally organized behind a front door first-time visitors can actually use.', 'Second Pres has real depth: a serious music program and a food ministry that feeds the neighborhood every week. A congregation like that needed a site that gives its programming real estate, not one I flattened down to a tidy three-section homepage that would have shortchanged the people who actually use it every week. So I kept the front door simple for guests, with all that depth one click away.', '[{"_key":"k67","_type":"block","children":[{"_key":"k66","_type":"span","marks":[],"text":"The brief"}],"markDefs":[],"style":"h2"},{"_key":"k69","_type":"block","children":[{"_key":"k68","_type":"span","marks":[],"text":"Second Presbyterian Church of Chicago is a historic congregation in the city''s South Loop, worshiping in a National Historic Landmark known as the Church of the Angels for the painted angels across its Arts and Crafts ceiling and its nine Tiffany windows. The programming runs as deep as the building''s history, and Sunday morning draws a mix of longtime members, neighbors, and first-time visitors trying to figure out what they are walking into. The site they came in with was working, but only for people who already knew where to look. Service times were buried. The sermon archive was hard to search. Staff updates were slow because the previous platform made small edits feel like a project."}],"markDefs":[],"style":"normal"},{"_key":"k6b","_type":"block","children":[{"_key":"k6a","_type":"span","marks":[],"text":"Leadership wanted a full rebuild, not a refresh. The brief was specific: fast front door for guests, deep resource library for members, and a CMS the communications staff could actually use on a Tuesday."}],"markDefs":[],"style":"normal"},{"_key":"k6d","_type":"block","children":[{"_key":"k6c","_type":"span","marks":[],"text":"The approach"}],"markDefs":[],"style":"h2"},{"_key":"k6f","_type":"block","children":[{"_key":"k6e","_type":"span","marks":[],"text":"We started by mapping the two distinct audiences and where they were likely to land. First-time visitors needed a short path to service times, parking, and what to expect on a Sunday morning. Regular members needed to reach the sermon archive, upcoming events, and ministry sign-ups in one click. The challenge was that these two groups needed completely different experiences from the same homepage."}],"markDefs":[],"style":"normal"},{"_key":"k6h","_type":"block","children":[{"_key":"k6g","_type":"span","marks":[],"text":"The architecture we settled on gives visitors a clear \"Plan a Visit\" lane that answers the four questions most of them have before they decide to show up. Everything else sits one level deeper: sermon archive, community group listings, music ministry, food outreach, weddings, and venue rental. The depth is there; it just does not crowd the front door."}],"markDefs":[],"style":"normal"},{"_key":"k6j","_type":"block","children":[{"_key":"k6i","_type":"span","marks":[],"text":"For the CMS, we chose Sanity so the team could manage the sermon archive, event calendar, and staff directory without touching code. Sermons carry full liturgical metadata, including who served, which hymns were sung, the lectionary day, and links to bulletins and worship notes. That makes the archive useful for both personal spiritual reference and denominational records."}],"markDefs":[],"style":"normal"},{"_key":"k6l","_type":"block","children":[{"_key":"k6k","_type":"span","marks":[],"text":"What we built"}],"markDefs":[],"style":"h2"},{"_key":"k6n","_type":"block","children":[{"_key":"k6m","_type":"span","marks":[],"text":"The full build, including the pieces above:"}],"markDefs":[],"style":"normal"},{"_key":"k6p","_type":"block","children":[{"_key":"k6o","_type":"span","marks":[],"text":"Headless CMS (Sanity) for sermons, events, staff, and all content the team updates weekly"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6r","_type":"block","children":[{"_key":"k6q","_type":"span","marks":[],"text":"Single-sourced worship time that populates the site header, footer, visit page, and Google structured data from one field, so a service-time change requires exactly one edit"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6t","_type":"block","children":[{"_key":"k6s","_type":"span","marks":[],"text":"Sermon archive with liturgical metadata: officiant, choir, lectionary day, hymns, bulletins, and streaming links"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6v","_type":"block","children":[{"_key":"k6u","_type":"span","marks":[],"text":"Events calendar covering both recurring ministry schedules and one-time events with detail pages"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6x","_type":"block","children":[{"_key":"k6w","_type":"span","marks":[],"text":"Get Involved section organized around four tracks: Grow (community groups), Serve (outreach partners), Kids, and Food Ministry (the weekday Lunch Bag program and the Sunday South Loop Community Table)"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6z","_type":"block","children":[{"_key":"k6y","_type":"span","marks":[],"text":"Weddings page with sanctuary history, a practical FAQ, and an inquiry workflow for couples booking the historic space"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k71","_type":"block","children":[{"_key":"k70","_type":"span","marks":[],"text":"Music page covering the quartette choir and the church''s historic Austin pipe organ in enough depth for visitors who care about sacred music"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k73","_type":"block","children":[{"_key":"k72","_type":"span","marks":[],"text":"Venue rental page for organizations wanting to use the building"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k75","_type":"block","children":[{"_key":"k74","_type":"span","marks":[],"text":"Give page connected to Vanco for online giving and designated gift categories"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}]', '{"id":"01M3ZCV1SY4FV3D5NNX2Q1CB0Z","provider":"local","filename":"second-presbyterian-chicago-home.png","mimeType":"image/png","width":1425,"height":5645,"blurhash":"LNLNrd_3azRj~W-;WBM{00ofayV[","dominantColor":"rgb(152,155,147)","alt":"The Second Presbyterian Church of Chicago homepage, scrolling top to bottom","meta":{"storageKey":"0QW5T0SMZJTW9GPTRZC9D7R4F0.png","caption":null,"blurhash":"LNLNrd_3azRj~W-;WBM{00ofayV[","dominantColor":"rgb(152,155,147)"}}', '{"id":"01M3ZCV3NGJJF2F909VXX6X04G","provider":"local","filename":"second-presbyterian-chicago-mobile.png","mimeType":"image/png","width":545,"height":4000,"blurhash":"LRLqIR%L%M%M4nj[xuj[~poft7of","dominantColor":"rgb(163,158,149)","alt":"","meta":{"storageKey":"2YP4HM87PQCTC36HSFHK13MSQA.png","caption":null,"blurhash":"LRLqIR%L%M%M4nj[xuj[~poft7of","dominantColor":"rgb(163,158,149)"}}', 'The Second Presbyterian Church of Chicago homepage, scrolling top to bottom', 'https://www.secondpreschicago.org', 'secondpreschicago.org', 'scroll', '[{"alt":"The Plan a Visit page on the new Second Presbyterian site","caption":"Service times, what to expect on a Sunday, and how to find the building, answered up front so a guest never has to dig for the basics.","image":{"alt":"The Plan a Visit page on the new Second Presbyterian site","blurhash":"LkI}kixtj[of4nWBWBj[~pofayfQ","dominantColor":"rgb(135,128,120)","filename":"second-presbyterian-chicago-feature-visit.png","height":900,"id":"01M3ZCV4XV5BBNXYFB05ZKYF55","meta":{"blurhash":"LkI}kixtj[of4nWBWBj[~pofayfQ","caption":null,"dominantColor":"rgb(135,128,120)","storageKey":"2BQ33AJC35T7PT9AC23TP210EX.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"left","title":"A front door built for first-time guests"},{"alt":"The sermon archive on the new Second Presbyterian site","caption":"Every message carries its full liturgical metadata, officiant, scripture, hymns, and a streaming link, so it serves personal study and the denominational record alike.","image":{"alt":"The sermon archive on the new Second Presbyterian site","blurhash":"LIP6,AD*t7~p?HIUWBxuV?^+RjD%","dominantColor":"rgb(195,195,186)","filename":"second-presbyterian-chicago-feature-sermons.png","height":900,"id":"01M3ZCV62GJZC50ZDTF1DQD00P","meta":{"blurhash":"LIP6,AD*t7~p?HIUWBxuV?^+RjD%","caption":null,"dominantColor":"rgb(195,195,186)","storageKey":"3VKHPTJPFYS8K2V3YFY1GQ82VZ.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"right","title":"A sermon archive with real depth"},{"alt":"The Get Involved section with its four ministry tracks","caption":"The week''s ministries sit behind four plain doors, Grow, Serve, Kids, and Food, so members reach their next step in a click without crowding the guest path.","image":{"alt":"The Get Involved section with its four ministry tracks","blurhash":"LCRV%$^+s+?b~qafoJayD$t6xuoJ","dominantColor":"rgb(239,233,223)","filename":"second-presbyterian-chicago-feature-community.png","height":900,"id":"01M3ZCV75549AKFWFDVG3RPMWC","meta":{"blurhash":"LCRV%$^+s+?b~qafoJayD$t6xuoJ","caption":null,"dominantColor":"rgb(239,233,223)","storageKey":"0BQW67FMEZ8BCHFEGXE8C4NREA.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"left","title":"Deep programming, clearly organized"}]', '{"id":"01M3ZCV86ZJ4ERG39NVYRZPEDW","provider":"local","filename":"second-presbyterian-chicago-before.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LMG8.fxuNHofE2D*tRtR~qt7aeRj","dominantColor":"rgb(127,119,112)","alt":"The previous Squarespace site for Second Presbyterian Church of Chicago","meta":{"storageKey":"5HTPX58J9BGHPHPYH9YMYFB8GM.png","caption":null,"blurhash":"LMG8.fxuNHofE2D*tRtR~qt7aeRj","dominantColor":"rgb(127,119,112)"}}', 'The previous Squarespace site for Second Presbyterian Church of Chicago', 'Before', '{"id":"01M3ZCPCKQKHGQKJW4XNYNKTB3","provider":"local","filename":"second-presbyterian-chicago.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)","alt":"The redesigned Second Presbyterian Church of Chicago homepage","meta":{"storageKey":"3YFB3122TA96GZZ57DZM67WXMZ.png","caption":null,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)"}}', 'The redesigned Second Presbyterian Church of Chicago homepage', 'After', '[{"text":"Anyone on the communications team can now add a sermon or update the staff directory in a few minutes, work that used to require a developer."},{"text":"First-time visitors get a clear front door to the church''s deep programming instead of a site that only worked for people who already knew where to look."},{"text":"A service-time change is now one edit that updates the header, footer, visit page, and Google''s structured data at once, instead of four separate edits that drift out of sync."},{"text":"Guests now have a short, clear path to service times, parking, and what to expect on a Sunday, the basics that used to be buried."}]');
